Given two strings txt and pat, the task is to return all indices of occurrences of pat within txt, ignoring the letter case (uppercase and lowercase characters are considered same).Examples:Input: txt = "aBcAb", pat = "aB"Output: [0, 3]Explanation: The string "ab" can match with any of the following strings: "ab", "Ab", "aB" and "AB". So, pat occurs twice in txt, first occurrence starts from index 0 and second from index 3.Input: txt = "aAAa", pat = "Aa"Output: [0, 1, 2]Explanation: The string "Aa" can match with any of the following strings: "aa", "aA", "Aa" and "AA". So, pat occurs thrice in txt, first occurrence starts from index 0, second from index 2 and third from index 3.Input: txt = "abba", pat = "aC"Output: []Explanation: There is no occurrence of "aC" in "abba".Try It YourselfTable of Content[Naive Approach] Matching with all substrings[Expected Approach] Using KMP Algorithm[Naive Approach] Matching with all substringsThe idea is, we start at every index in the text and compare it with the first character of the pattern, if they match we move to the next character in both text and pattern. Also, before matching the characters, we can convert both the characters to lower case to ignore the case. If there is a mismatch, we start the same process for the next index of the text. 
            C++

    // C++ Program for Case Insensitive Search by matching  
// with all substrings

#include <iostream>
#include <vector>
using namespace std;

vector<int> search(string &txt, string &pat) {
    vector<int> res;
    int n = txt.length();
    int m = pat.length();

    // Macth the pattern with all substrings of txt
	for(int i = 0; i < n - m + 1; i++) {
		bool found = true;
    	for(int j = 0; j < m; j++) {

            // Convert the characters to lower case
        	if(tolower(txt[i + j]) != tolower(pat[j])) {
            	found = false;
                break;
            }
        }
        if(found)
            res.push_back(i);
    }
    return res;
}

int main() {
	string txt = "aBcAb", pat = "ab";

    vector<int> res = search(txt, pat);
    for(int idx : res)
        cout << idx << " ";
}


